from html.parser import HTMLParser
import os

class Checker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.body_attrs = {}
        self.section_attrs = []
        self.section_ids = set()
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == 'body':
            self.body_attrs = a
        if tag == 'section':
            self.section_attrs.append(a)
            if 'id' in a:
                self.section_ids.add(a['id'])

